import{_ as l,o as a,c as o,a2 as t}from"./chunks/framework.BS0bAV7E.js";const u=JSON.parse('{"title":"代码风格","description":"","frontmatter":{},"headers":[],"relativePath":"zh/dev/coding-style.md","filePath":"zh/dev/coding-style.md"}'),i={name:"zh/dev/coding-style.md"};function d(c,e,r,h,s,n){return a(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="代码风格" tabindex="-1">代码风格 <a class="header-anchor" href="#代码风格" aria-label="Permalink to &quot;代码风格&quot;">​</a></h1><p>代码树风格自洽；遵循现有风格。</p><h2 id="c" tabindex="-1">C <a class="header-anchor" href="#c" aria-label="Permalink to &quot;C&quot;">​</a></h2><ul><li>C11 (<code>-std=gnu11</code>)，4 空格缩进，K&amp;R 大括号风格，.c/.h 文件中不使用制表符。</li><li>类型：使用内核的固定宽度类型集（<code>u8/u16/u32/u64/s8/...</code>，来自 <code>types.h</code>）- 不使用 uint8_t 这样的拼写。</li><li>当类型重要时，每行只声明一个变量；尽可能地进行初始化。</li><li>每个文件开头都必须包含 SPDX 版权注释块和一个 Purpose 段落，说明该文件存在的原因。未来的读者（和文档生成器）依赖于此。</li><li>函数注释：约定、参数、返回码 - 特别是每个负数返回值。</li><li>错误处理：检查、用清晰的报告消息报告、然后回滚 - 绝不能泄露半初始化的设备注册。</li></ul><h2 id="汇编" tabindex="-1">汇编 <a class="header-anchor" href="#汇编" aria-label="Permalink to &quot;汇编&quot;">​</a></h2><ul><li><code>.S</code> 文件（预处理）：boot.S 和架构跳板是参考标准。在每个入口点注释 ABI。</li></ul><h2 id="shell-命令" tabindex="-1">Shell 命令 <a class="header-anchor" href="#shell-命令" aria-label="Permalink to &quot;Shell 命令&quot;">​</a></h2><ul><li>使用 <code>shell_register_command_ex</code> 和工作包标签进行注册，以确保 <code>help -w</code> 的准确性。</li><li>单行帮助信息，参数错误时打印 <code>usage:</code>，失败时以非零退出码退出。</li><li>仅使用 ASCII 字符。</li></ul><h2 id="命名" tabindex="-1">命名 <a class="header-anchor" href="#命名" aria-label="Permalink to &quot;命名&quot;">​</a></h2><ul><li>文件：<code>kernel/&lt;area&gt;/core_&lt;thing&gt;.c</code>，<code>drivers/&lt;bus&gt;/driver_&lt;hw&gt;.c</code>，<code>shell/shell_cmds_&lt;domain&gt;.c</code>，<code>fs/fs_&lt;fs&gt;.c</code> - 代码树的布局就是分类标准（文档生成器按此分组）。</li><li>符号：<code>&lt;module&gt;_&lt;verb&gt;_&lt;object&gt;</code>（例如 <code>driver_block_flush</code>，<code>klog_write</code>，<code>ota_ab_install</code>）。静态辅助函数保持文件局部性。</li><li>全大写常量带模块前缀（<code>OC_MB2_TAG_END</code>，<code>SHELL_MAX_COMMANDS</code>）。</li></ul><h2 id="限制是设计的一部分" tabindex="-1">限制是设计的一部分 <a class="header-anchor" href="#限制是设计的一部分" aria-label="Permalink to &quot;限制是设计的一部分&quot;">​</a></h2><p>当你添加一个有界表时，限制常量必须附带注释解释该数值（参见 shell.h 中的 <code>SHELL_MAX_COMMANDS</code> - 232-&gt;256 的历史记录在定义处有文档）。保持这种纪律：下一个需要调整它的人需要了解背景。</p><h2 id="禁止事项" tabindex="-1">禁止事项 <a class="header-anchor" href="#禁止事项" aria-label="Permalink to &quot;禁止事项&quot;">​</a></h2><ul><li>没有&quot;留作后用&quot;的死代码 - 删除它；git 会记住。</li><li>没有无声截断 - 拒绝并给出消息（别名的值是典范：完整存储或拒绝）。</li><li>没有 <code>// TODO</code> 而不带 BUG- 编号或工作包引用。</li><li>没有新的第三方代码：代码树是原创的，Apache 2.0 许可，且保持不变。</li></ul>',14)])])}const m=l(i,[["render",d]]);export{u as __pageData,m as default};
